import sys
from collections import defaultdict, deque

def read_ints():
    return list(map(int, sys.stdin.readline().strip().split()))

n, m = read_ints()
graph = defaultdict(list)

for _ in range(m):
    a, b = read_ints()
    graph[a].append(b)

# Find vertices that are reachable in at most two moves
reachable = [set() for _ in range(n + 1)]

def bfs(start):
    visited = set()
    queue = deque([start])
    distance = 0
    while queue and distance <= 2:
        for _ in range(len(queue)):
            node = queue.popleft()
            if node not in visited:
                visited.add(node)
                reachable[start].add(node)
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        queue.append(neighbor)
        distance += 1

for i in range(1, n + 1):
    bfs(i)

# Find the set Q
